use fitig_engine::{authentication::Session,CrawlOptions,CrawlProfile,Page};
use std::{io::{Read,Write},net::TcpListener,path::PathBuf,sync::{Arc,Mutex,atomic::{AtomicBool,AtomicUsize,Ordering}},time::Duration};
use base64::Engine;
#[derive(Clone)]struct Request{path:String,host:String,has_auth:bool,authorized:bool}
struct Site{origin:String,requests:Arc<Mutex<Vec<Request>>>,stop:Arc<AtomicBool>,worker:Option<std::thread::JoinHandle<()>>}
impl Site{fn new(expected:Option<String>,handler:impl Fn(&str,&str,bool)->(u16,String,Option<String>)+Send+'static)->Self{
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let origin=format!("http://{}",listener.local_addr().unwrap());let requests=Arc::new(Mutex::new(Vec::new()));let seen=requests.clone();let stop=Arc::new(AtomicBool::new(false));let done=stop.clone();let worker=std::thread::spawn(move||{while !done.load(Ordering::SeqCst){match listener.accept(){Ok((mut stream,_))=>{stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(Duration::from_secs(3))).unwrap();let mut bytes=Vec::new();let mut one=[0];while bytes.len()<32768&&!bytes.ends_with(b"\r\n\r\n"){if stream.read(&mut one).unwrap_or(0)!=1{break}bytes.push(one[0])}let raw=String::from_utf8_lossy(&bytes);let path=raw.split_whitespace().nth(1).unwrap_or("");let header=|name:&str|raw.lines().find_map(|line|line.split_once(':').filter(|(key,_)|key.eq_ignore_ascii_case(name)).map(|(_,value)|value.trim()));let host=header("host").unwrap_or("");let value=header("authorization");let authorized=value.is_some()&&value==expected.as_deref();seen.lock().unwrap().push(Request{path:path.into(),host:host.into(),has_auth:value.is_some(),authorized});let(status,body,location)=handler(path,host,authorized);let extra=location.map(|url|format!("Location: {url}\r\n")).unwrap_or_default();let challenge=if status==401{"WWW-Authenticate: Basic realm=\"owned\", charset=\"UTF-8\"\r\n"}else{""};let response=format!("HTTP/1.1 {status} Fixture\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n{extra}{challenge}\r\n{body}",body.len());let _=stream.write_all(response.as_bytes());},Err(_)=>std::thread::sleep(Duration::from_millis(1))}}});Self{origin,requests,stop,worker:Some(worker)}}}
impl Drop for Site{fn drop(&mut self){self.stop.store(true,Ordering::SeqCst);self.worker.take().unwrap().join().unwrap()}}
static COUNTER:AtomicUsize=AtomicUsize::new(0);
struct Project(PathBuf);impl Project{fn new()->Self{let root=std::env::temp_dir().join(format!("fitig-auth-{}-{}",std::process::id(),COUNTER.fetch_add(1,Ordering::SeqCst)));std::fs::create_dir(&root).unwrap();Self(root)}fn db(&self)->String{self.0.join("project.sqlite").to_string_lossy().into_owned()}}
impl Drop for Project{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn run(site:&Site,project:&Project,profile:CrawlProfile,session:Option<Session>,resume:bool,limit:usize)->fitig_engine::Result<Vec<Page>>{fitig_engine::crawl_with_authentication_and_renderer(CrawlOptions{url:site.origin.clone()+"/",db:project.db(),limit,delay_ms:0,resume},None,profile,session,fitig_engine::render::render,|_|{})}
fn encoded(user:&str,password:&str)->String{format!("Basic {}",base64::engine::general_purpose::STANDARD.encode(format!("{user}:{password}")))}
#[test]fn cli_reads_credentials_only_from_explicit_child_environment(){let password="owned-cli-fixture-password";let authorization=encoded("cli-user",password);let site=Site::new(Some(authorization.clone()),|path,_,authorized|if !authorized{(401,"Authentication required".into(),None)}else{(200,if path=="/robots.txt"{"User-agent: *\nAllow: /"}else{"<title>Protected CLI</title>"}.into(),None)});let project=Project::new();let profile=project.0.join("profile.json");std::fs::write(&profile,serde_json::to_vec(&CrawlProfile{http_auth_origin:site.origin.clone(),..Default::default()}).unwrap()).unwrap();let output=std::process::Command::new(env!("CARGO_BIN_EXE_fitig-engine")).args(["crawl","--url",&(site.origin.clone()+"/"),"--db",&project.db(),"--profile",profile.to_str().unwrap(),"--basic-auth-env","--delay-ms","0"]).env("FITIG_HTTP_AUTH_USERNAME","cli-user").env("FITIG_HTTP_AUTH_PASSWORD",password).output().unwrap();assert!(output.status.success());let text=format!("{}{}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));assert!(!text.contains(password)&&!text.contains(&authorization));let pages=fitig_engine::load_pages(&project.db()).unwrap();assert_eq!(pages[0].title,"Protected CLI");let serialized=String::from_utf8_lossy(&std::fs::read(project.db()).unwrap()).into_owned();assert!(!serialized.contains(password)&&!serialized.contains(&authorization));}
#[test]fn authenticated_robots_pages_redirects_and_external_checks_keep_credentials_origin_scoped(){
 let user="משתמש";let password="owned-fixture-secret-47";let authorization=encoded(user,password);
 let peer=Site::new(None,|path,_,_|(200,if path=="/robots.txt"{"User-agent: *\nAllow: /"}else{"<title>External</title><a href='/never-traverse'>never</a>"}.into(),None));let peer_url=peer.origin.clone();
 let site=Site::new(Some(authorization.clone()),move|path,host,authorized|{if host.starts_with("localhost:"){return (200,if path=="/robots.txt"{"User-agent: *\nAllow: /"}else{"<title>Other hostname</title>"}.into(),None)}if !authorized{return(401,"Authentication required".into(),None)}match path{"/robots.txt"=>(200,"User-agent: *\nAllow: /\nDisallow: /blocked".into(),None),"/"=>(200,format!("<title>Protected</title><a href='/a'>אימות</a><a href='/denied'>denied</a><a href='/jump'>redirect</a><a href='/blocked'>robots</a><a href='http://localhost:{}/external-host'>other host</a>",host.split(':').last().unwrap()),None),"/jump"=>(302,String::new(),Some(peer_url.clone()+"/external")),"/denied"=>(401,"Denied even with credentials".into(),None),_=>(200,"<title>שלום מוגן</title>".into(),None)}});
 let project=Project::new();let profile=CrawlProfile{http_auth_origin:site.origin.clone(),check_external:true,..Default::default()};let pages=run(&site,&project,profile.clone(),Some(Session::new(&site.origin,user,password).unwrap()),false,0).unwrap();assert_eq!(pages.len(),7);assert_eq!(pages.iter().find(|page|page.url.ends_with("/a")).unwrap().title,"שלום מוגן");assert_eq!(pages.iter().find(|page|page.url.ends_with("/denied")).unwrap().status,401);assert_eq!(pages.iter().find(|page|page.url.ends_with("/blocked")).unwrap().error,"Blocked by robots.txt");
 let requests=site.requests.lock().unwrap();assert!(requests.iter().filter(|request|request.host.starts_with("127.0.0.1:")).all(|request|request.authorized));assert!(requests.iter().any(|request|request.path=="/robots.txt"&&request.authorized));assert!(requests.iter().filter(|request|request.host.starts_with("localhost:")).all(|request|!request.has_auth));assert_eq!(requests.iter().filter(|request|request.path=="/denied").count(),1);assert!(!requests.iter().any(|request|request.path=="/blocked"));drop(requests);
 let peer_requests=peer.requests.lock().unwrap();assert!(peer_requests.iter().any(|request|request.path=="/external"));assert!(peer_requests.iter().all(|request|!request.has_auth));assert!(!peer_requests.iter().any(|request|request.path=="/never-traverse"));drop(peer_requests);
 assert_eq!(fitig_engine::project_profile(&project.db()).unwrap(),profile);let snapshot=serde_json::to_vec(&pages).unwrap();let db=std::fs::read(project.db()).unwrap();for bytes in [&snapshot,&db]{let value=String::from_utf8_lossy(bytes);assert!(!value.contains(password)&&!value.contains(&authorization)&&!value.contains(user));}assert!(!serde_json::to_string(&fitig_engine::project_profile(&project.db()).unwrap()).unwrap().contains("password"));
}
#[test]fn missing_mismatched_or_rendering_authentication_fails_before_database_creation_or_network(){let site=Site::new(None,|_,_,_|panic!("No HTTP expected"));let profile=CrawlProfile{http_auth_origin:site.origin.clone(),..Default::default()};for(case,session)in [(profile.clone(),None),(profile.clone(),Some(Session::new("https://other.test","user","secret").unwrap())),(CrawlProfile{rendering:fitig_engine::render::Rendering{enabled:true,..Default::default()},..profile.clone()},Some(Session::new(&site.origin,"user","secret").unwrap()))]{let project=Project::new();assert!(run(&site,&project,case,session,false,0).is_err());assert!(!std::path::Path::new(&project.db()).exists())}assert!(site.requests.lock().unwrap().is_empty());}
#[test]fn resume_requires_reentry_and_wrong_credentials_do_not_fabricate_success(){let password="owned-resume-fixture-secret";let site=Site::new(Some(encoded("user",password)),|path,_,authorized|if !authorized{(401,"Authentication required".into(),None)}else if path=="/robots.txt"{(200,"User-agent: *\nAllow: /".into(),None)}else if path=="/"{(200,"<a href='/next'>next</a>".into(),None)}else{(200,"<title>Resumed</title>".into(),None)});let profile=CrawlProfile{http_auth_origin:site.origin.clone(),..Default::default()};let project=Project::new();let session=||Some(Session::new(&site.origin,"user",password).unwrap());assert_eq!(run(&site,&project,profile.clone(),session(),false,1).unwrap().len(),1);let before=std::fs::read(project.db()).unwrap();assert!(run(&site,&project,profile.clone(),None,true,0).is_err());assert_eq!(std::fs::read(project.db()).unwrap(),before);assert_eq!(run(&site,&project,profile.clone(),session(),true,0).unwrap().len(),2);let wrong=Project::new();let pages=run(&site,&wrong,profile,Some(Session::new(&site.origin,"user","wrong").unwrap()),false,1).unwrap();assert_eq!(pages[0].status,0);assert_eq!(pages[0].error,"Blocked by robots.txt");}
